/* ies_lights: lamps shaped by IES photometric files (Light3D `ies_profile`,
 * cartwheel/lighting.h).
 *
 * Left to right over a floor and a wall at night: a spot light with a ring
 * profile (a soft centre inside a bright ring) that casts a crate's shadow, a
 * spot light with a street lamp's profile (it throws its light forward, to
 * the camera's side, and little behind), an omni light with a lantern's
 * profile (four bright faces and dark bars between them, on the wall and the
 * floor alike) and a plain spot light with its cone for comparison. The .ies
 * files are generated by gen.mjs.
 *
 * The street lamp turns about its axis (a quarter turn every four seconds,
 * eased): its pool of light turns with it, which a plain cone would not show.
 *
 * IES_OFF=1 takes every profile away at tick 2 (the gate's control: the
 * state and the picture differ).
 *
 * Debug fields: ies.lights (clustered lights shaped by a profile), ies.clustered
 * (clustered lights), ies.tick. */
#include "cartwheel/debug.h"
#include "cartwheel/lighting.h"
#include "cartwheel/math.h"
#include "cartwheel/platform.h"
#include "cartwheel/scene_file.h"

static int32_t ies_lights, clustered, tick32;
static bool off;

static cw_node node(const char *path) { return cw_node_get(cw_tree_root(cw_scene_app_tree()), path); }

static void init(void *u) {
  (void)u;
  cw_debug_i32("ies.lights", &ies_lights);
  cw_debug_i32("ies.clustered", &clustered);
  cw_debug_i32("ies.tick", &tick32);
}

static void fixed(void *u, double dt) {
  (void)u;
  (void)dt;
  tick32++;
  if (tick32 == 2 && cw_test_env("IES_OFF")) { /* the gate's switch, from the first frame every host can set it */
    off = true;
    static const char *const lamps[] = { "World/Ring", "World/Street", "World/Lantern" };
    for (int i = 0; i < 3; i++) cw_node_set(node(lamps[i]), "ies_profile", (cw_value){ CW_T_RES });
  }
  /* the street lamp's twist: 0 to a quarter turn and back, eased (about its own axis, which points down) */
  float t = (float)(tick32 % 480) / 480.0f;
  float s = 0.5f - 0.5f * cw_cos(t * 2 * CW_PI);
  cw_node_set(node("World/Street"), "rotation", cw_val_vec3(-CW_PI / 2, 0, s * CW_PI / 2));
  cw_lighting_stats st;
  cw_lighting_get_stats(cw_scene_app_tree(), &st);
  ies_lights = st.ies;
  clustered = st.clustered;
}

cw_app_desc cw_main(int argc, char **argv) {
  (void)argc;
  (void)argv;
  static cw_app_desc base = { .title = "ies_lights", .width = 960, .height = 540, .debug = true, .init = init, .fixed_update = fixed };
  return cw_scene_app("main.cwscene", &base);
}
